package com.witchersbestiary.client.merchant;
import com.witchersbestiary.merchant.*;import net.minecraft.util.Identifier;
public final class MerchantClient {
 public static void initialize(){net.minecraft.client.gui.screen.ingame.HandledScreens.register(ArcaneMerchants.SCREEN,MerchantScreen::new);net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking.registerGlobalReceiver(MerchantPackets.State.ID,(packet,ctx)->ctx.client().execute(()->{if(ctx.client().player!=null&&ctx.client().player.currentScreenHandler instanceof MerchantHandler h&&h.syncId==packet.sync()){h.session=packet.session();h.nonce=packet.sequence();var snapshot=com.google.gson.JsonParser.parseString(packet.json()).getAsJsonObject();boolean changed=!snapshot.equals(h.snapshot);h.snapshot=snapshot;if(changed&&ctx.client().currentScreen instanceof MerchantScreen screen)screen.update();}}));
 net.fabricmc.fabric.api.client.rendering.v1.EntityRendererRegistry.register(ArcaneMerchants.TYPE,c->new software.bernie.geckolib.renderer.GeoEntityRenderer<ArcaneMerchant>(c,new software.bernie.geckolib.model.GeoModel<ArcaneMerchant>(){
  public Identifier getModelResource(ArcaneMerchant e){return Identifier.of("witchersbestiary:geo/arcane_merchant.geo.json");}public Identifier getTextureResource(ArcaneMerchant e){return Identifier.of("witchersbestiary:textures/entity/arcane_merchant.png");}public Identifier getAnimationResource(ArcaneMerchant e){return Identifier.of("witchersbestiary:animations/arcane_merchant.animation.json");}
  @Override public void setCustomAnimations(ArcaneMerchant e,long instance,software.bernie.geckolib.animation.AnimationState<ArcaneMerchant> state){super.setCustomAnimations(e,instance,state);var head=getAnimationProcessor().getBone("head");var data=state.getData(software.bernie.geckolib.constant.DataTickets.ENTITY_MODEL_DATA);if(head!=null&&data!=null){head.setRotX(data.headPitch()*(float)Math.PI/180);head.setRotY(data.netHeadYaw()*(float)Math.PI/180);}}
 }));}
}
